namespace MediPassPlus.Application.Records;

/// <summary>
/// A file that <see cref="IReportStorage"/> has written. The name is generated by the server; the client's original
/// file name is never part of it (FR-REC-06, NFR-SEC-09).
/// </summary>
/// <param name="StoredFileName">The random name, including the extension derived from the validated media type.</param>
/// <param name="SizeBytes">The number of bytes actually written, counted while copying.</param>
public sealed record StoredReportFile(string StoredFileName, long SizeBytes);
